import{_ as s,o as r,c as o,a5 as e}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse(`{"title":"第十一章：支持 .json 模块加载（兼容 import 与 require）","description":"非常好，我们继续进入： 📦 ✅ 本章目标： 支持加载 .json 文件 允许通过 import data from './x.json' 或 require('./x.json') 获取 JSON 对象 模拟 Node.js 中对 JSON 模块的处理方式 🧱 项目结构（新增）。","frontmatter":{"title":"第十一章：支持 .json 模块加载（兼容 import 与 require）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"非常好，我们继续进入： 📦 ✅ 本章目标： 支持加载 .json 文件 允许通过 import data from './x.json' 或 require('./x.json') 获取 JSON 对象 模拟 Node.js 中对 JSON 模块的处理方式 🧱 项目结构（新增）。","sidebarWeight":47,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第十一章：支持 .json 模块加载（兼容 import 与 require）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十一章：支持 .json 模块加载（兼容 import 与 require）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十一章：支持 .json 模块加载（兼容 import 与 require）.md"}`),n={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十一章：支持 .json 模块加载（兼容 import 与 require）.md"};function a(d,t,i,p,g,l){return r(),o("div",null,[...t[0]||(t[0]=[e('<div><h1 id="第十一章-支持-json-模块加载-兼容-import-与-require" tabindex="-1">第十一章：支持 .json 模块加载（兼容 import 与 require） <a class="header-anchor" href="#第十一章-支持-json-模块加载-兼容-import-与-require" aria-label="Permalink to &quot;第十一章：支持 .json 模块加载（兼容 import 与 require）&quot;">​</a></h1><blockquote><p>本节目标：理解“第十一章：支持 .json 模块加载（兼容 import 与 require）”的核心思路，并能把它用于实际开发或面试表达。 非常好，我们继续进入：</p></blockquote><p><strong>📦</strong> ✅ 本章目标：</p><ul><li>支持加载 .json 文件</li><li>允许通过 import data from &#39;./x.json&#39; 或 require(&#39;./x.json&#39;) 获取 JSON 对象</li><li>模拟 Node.js 中对 JSON 模块的处理方式</li></ul><p><strong>🧱</strong> <strong>项目结构（新增）</strong> jsonloader/├── src/│ ├── data.json│ ├── esm.mjs│ ├── cjs.js│ └── main.mjs├── bundler.js└── dist/bundle.js</p><p><strong>📄</strong> <strong>src/data.json</strong> { &quot;appName&quot;: &quot;MiniBundler&quot;, &quot;version&quot;: &quot;1.0.0&quot;} <strong>📄</strong> <strong>src/esm.mjs</strong> import data from &#39;./data.json&#39;;export const msg = &#39;App: &#39; + data.appName; <strong>📄</strong> <strong>src/cjs.js</strong> const data = require(&#39;./data.json&#39;);module.exports = { ver: data.version }; <strong>📄</strong> <strong>src/main.mjs</strong> import { msg } from &#39;./esm.mjs&#39;;const { ver } = require(&#39;./cjs.js&#39;); console.log(msg);console.log(&#39;Version:&#39;, ver);</p><p><strong>🔧</strong> <strong>修改 bundler.js（支持 .json 模块）</strong><strong>✅</strong> <strong>步骤 1：parseModule 增加 JSON 支持</strong> function parseModule(filePath) { const absPath = path.resolve(filePath); if (visited.has(absPath)) return null; visited.add(absPath); const ext = path.extname(absPath); const rawCode = fs.readFileSync(absPath, &#39;utf-8&#39;); const deps = []; const isESM = ext === &#39;.mjs&#39;; const isJSON = ext === &#39;.json&#39;; if (isJSON) { return { id: id++, absPath, rawCode, deps: [], isESM, isJSON: true }; } if (isESM) { const ast = acorn.parse(rawCode, { sourceType: &#39;module&#39;, ecmaVersion: &#39;latest&#39; }); for (const node of ast.body) { if (node.type === &#39;ImportDeclaration&#39;) { deps.push(node.source.value); } } } else { const requireRegex = /require(<a href="./.+">&#39;&quot;</a>[&#39;&quot;])/g; let match; while ((match = requireRegex.exec(rawCode))) { deps.push(match[1]); } } return { id: id++, absPath, rawCode, deps, isESM, isJSON: false };}</p><p><strong>✅</strong> <strong>步骤 2：transformCode 支持 JSON 转换</strong> 在 transformCode(mod) 中添加： if (mod.isJSON) { const parsed = JSON.parse(mod.rawCode); return <code>Object.assign(exports, ${JSON.stringify(parsed)});</code>;} 并在后面补上 fallback： // fallbackreturn code;</p><p><strong>✅</strong> <strong>步骤 3：确保路径后缀自动补全（导入时）</strong> 你可以在 parseModule() 和 transformCode() 中确保： const ensureExt = (filepath) =&gt; [&#39;.mjs&#39;, &#39;.js&#39;, &#39;.json&#39;].some(ext =&gt; filepath.endsWith(ext)) ? filepath : filepath + &#39;.js&#39;; // 默认补 js，你也可以更智能 // 解析依赖路径时：const resolved = path.resolve(path.dirname(mod.absPath), ensureExt(dep));</p><p><strong>🚀</strong> <strong>打包运行</strong> node bundler.js src/main.mjs --out dist/bundle.jsnode dist/bundle.js</p><p><strong>✅</strong> <strong>输出结果：</strong> App: MiniBundlerVersion: 1.0.0</p><p><strong>✅</strong> <strong>本章成果总结</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>实现</strong></td></tr><tr><td>JSON 模块解析</td><td>✔</td></tr><tr><td>import JSON 支持</td><td>✔</td></tr><tr><td>require JSON 支持</td><td>✔</td></tr><tr><td>JSON 自动序列化导出</td><td>✔</td></tr><tr><td>多种模块类型混用支持</td><td>✔</td></tr></tbody></table><p><strong>🔮</strong> <strong>下一章预告（第十二章）</strong> 下一步，我们可以进入： <strong>支持生成模块间依赖图可视化（Graphviz 或 HTML 格式）</strong> 让你能<strong>一眼看出模块结构</strong>、依赖关系，甚至是打包优化点，像 Rollup、Webpack 分析图一样。 是否继续？我可以帮你生成模块依赖关系图 HTML 或 DOT 文件 ✅ &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const m=s(n,[["render",a]]);export{c as __pageData,m as default};
